// Content with portions generated by generative AI platform
package org.eclipse.kura.internal.rest.auth.jwt;

import java.util.ArrayList;
import java.util.List;

import org.junit.Test;

import jakarta.ws.rs.core.Response.Status;

public class RefreshTokenFamilyPasswordChangeTest extends AbstractRefreshTokenFamilyScenario {

    private static final int OK = Status.OK.getStatusCode();
    private static final int UNAUTHORIZED = Status.UNAUTHORIZED.getStatusCode();

    private final List<String> refreshTokens = new ArrayList<>();

    @Test
    public void anUnchangedPasswordKeepsTheFamilyActive() {
        givenThePasswordIs("first");
        givenTheOwnerLoggedIn(1);

        whenTheRefreshTokensAreExchanged();

        thenTheExchangeStatusesAre(OK);
    }

    @Test
    public void changingThePasswordRevokesEveryFamilyOfTheIdentity() {
        givenThePasswordIs("first");
        givenTheOwnerLoggedIn(2);
        givenThePasswordIs("second");

        whenTheRefreshTokensAreExchanged();

        thenTheExchangeStatusesAre(UNAUTHORIZED, UNAUTHORIZED);
    }

    @Test
    public void restoringThePreviousPasswordDoesNotReviveTheFamily() {
        givenThePasswordIs("first");
        givenTheOwnerLoggedIn(1);
        givenThePasswordIs("second");
        givenTheRefreshTokensWereExchanged();
        givenThePasswordIs("first");

        whenTheRefreshTokensAreExchanged();

        thenTheExchangeStatusesAre(UNAUTHORIZED, UNAUTHORIZED);
    }

    private void givenThePasswordIs(final String password) {
        setPassword(IDENTITY, password);
    }

    private void givenTheOwnerLoggedIn(final int sessions) {
        for (int i = 0; i < sessions; i++) {
            this.refreshTokens.add(login().refreshToken());
        }
    }

    private void givenTheRefreshTokensWereExchanged() {
        this.refreshTokens.forEach(this::exchange);
    }

    private void whenTheRefreshTokensAreExchanged() {
        this.refreshTokens.forEach(this::exchange);
    }
}
